-- The allocation grid itself: 4,724 rows, 857 clients, six roles.
--
-- The schema lives in customer_allocations.sql; this is the DATA, which until
-- now existed only in a clone because the spreadsheet import was run ad hoc and
-- never committed. Without these rows every management section renders "no
-- account manager", and three endpoints (/fires, /slow-responders, /owner-load)
-- fail outright against a database where the table is missing entirely.
--
-- Source: "Allocation details for email sentiment tool.xlsx", sheet "with
-- domains" — the firm's system of record for who holds which role.
--
-- IDS ARE RESOLVED HERE, NOT COPIED. Only the grid's own columns are inserted;
-- customer_id and user_id are then looked up against THIS database's customers
-- and users. Copying the clone's UUIDs would appear to work and silently join
-- to nothing wherever the two diverge — the same class of silent-empty failure
-- that hid a broken /waiting endpoint in production for weeks.
--
-- Safe to re-run: every statement is idempotent, and the unique index makes the
-- insert a no-op on a second pass.

\set ON_ERROR_STOP on
BEGIN;

CREATE TABLE IF NOT EXISTS customer_allocations (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id     uuid NOT NULL,
  client_id     text,
  client_name   text NOT NULL,
  client_key    text NOT NULL,
  customer_id   uuid,
  role          text NOT NULL,
  email         text NOT NULL,
  user_id       uuid,
  loaded_at     timestamptz NOT NULL DEFAULT now()
);

CREATE UNIQUE INDEX IF NOT EXISTS customer_allocations_unique
  ON customer_allocations (tenant_id, client_key, role, email);
CREATE INDEX IF NOT EXISTS customer_allocations_customer
  ON customer_allocations (tenant_id, customer_id) WHERE customer_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS customer_allocations_user
  ON customer_allocations (tenant_id, user_id) WHERE user_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS customer_allocations_role
  ON customer_allocations (tenant_id, role);

-- The grid rows. tenant_id is taken from this database, not hardcoded.
INSERT INTO customer_allocations (tenant_id, client_id, client_name, client_key, role, email)
SELECT t.id, v.client_id, v.client_name, v.client_key, v.role, v.email
FROM (SELECT id FROM tenants ORDER BY created_at LIMIT 1) t,
