ON CONFLICT (tenant_id, client_key, role, email) DO NOTHING;

-- Resolve the customer by NORMALISED NAME, the rule the grid itself follows:
-- lower(name) with non-alphanumerics stripped. Verified exact on all 4,724 rows.
-- Only 116 carry a domain, while 774 of 857 clients match on name.
UPDATE customer_allocations al
SET customer_id = c.id
FROM customers c
WHERE al.customer_id IS NULL
  AND al.tenant_id = c.tenant_id
  AND lower(regexp_replace(c.name, '[^a-zA-Z0-9]', '', 'g')) = al.client_key;

-- Resolve the person by email.
UPDATE customer_allocations al
SET user_id = u.id
FROM users u
WHERE al.user_id IS NULL
  AND al.tenant_id = u.tenant_id
  AND lower(u.email) = lower(al.email);

COMMIT;

-- What landed. Expect roughly: 4724 rows, ~4270 with a customer, ~99.8% with a user.
SELECT count(*) AS rows,
       count(customer_id) AS matched_customer,
       count(user_id) AS matched_user,
       count(DISTINCT client_key) AS clients
FROM customer_allocations;
